SELECT author_employee_id
  FROM post_comment
 WHERE company_id = #{companyId}
   AND post_id = #{postId}
   AND post_comment_id = #{commentId}
   AND deleted_at IS NULL

mapper.update:
UPDATE post_comment
   SET deleted_at = CAST(SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul' AS TIMESTAMP)
 WHERE company_id = #{companyId}
   AND post_id = #{postId}
   AND post_comment_id = #{commentId}
   AND deleted_at IS NULL

